import fitz
import os

print("="*70)
print("FINAL VERIFICATION OF ALL ANONYMIZED PAPERS")
print("="*70)

all_papers_clean = True

# Define what to check for each paper
paper_checks = {
    1: {
        "author_names": ["Yueqian Lin", "Zhengmian Hu", "Qinsi Wang", "Yudong Liu", 
                         "Hengfan Zhang", "Jayakumar Subramanian", "Nikos Vlassis", 
                         "Helen", "Yiran Chen"],
        "affiliations": ["Duke University", "Adobe", "San Jose"],
        "emails": ["@duke.edu", "@adobe.com"],
    },
    2: {
        "author_names": ["Jiatong Shi", "Yueqian Lin", "Xinyi Bai", "Keyi Zhang", 
                         "Yuning Wu", "Yuxun Tang", "Yifeng Yu", "Qin Jin", 
                         "Shinji Watanabe", "Shengyuan Xu", "Pengcheng Zhu"],
        "affiliations": ["Carnegie Mellon", "Duke Kunshan", "Cornell", 
                        "Multimodal Art Projection", "Renmin University", "Georgia Tech"],
        "emails": ["@cmu.edu"],
    },
    3: {
        "author_names": ["Yueqian Lin", "Yuzhe Fu", "Jingyang Zhang", "Yudong Liu",
                        "Jianyi Zhang", "Jingwei Sun", "Hai Li", "Yiran Chen"],
        "affiliations": ["Duke University", "Durham"],
        "emails": ["@duke.edu"],
        "other": ["ICML Workshop", "Vancouver", "NSF 2112562"],
    },
}

for paper_num in range(1, 4):
    doc = fitz.open(f"/root/redacted/paper{paper_num}.pdf")

    # Collect all text from the document
    full_text = ""
    for page in doc:
        full_text += page.get_text()

    checks = paper_checks[paper_num]
    issues = []

    # Check author names
    for name in checks["author_names"]:
        if name.lower() in full_text.lower():
            issues.append(f"Author: {name}")

    # Check affiliations
    for affil in checks["affiliations"]:
        if affil.lower() in full_text.lower():
            issues.append(f"Affiliation: {affil}")

    # Check emails
    for email in checks["emails"]:
        if email.lower() in full_text.lower():
            issues.append(f"Email pattern: {email}")

    # Check other patterns if present
    if "other" in checks:
        for pattern in checks["other"]:
            if pattern.lower() in full_text.lower():
                issues.append(f"Other: {pattern}")

    doc.close()

    # Report results
    file_path = f"/root/redacted/paper{paper_num}.pdf"
    file_size = os.path.getsize(file_path)

    if not issues:
        print(f"\n✓ Paper {paper_num}: CLEAN ({file_size:,} bytes)")
        print(f"   All author-identifying info successfully redacted")
    else:
        print(f"\n✗ Paper {paper_num}: {len(issues)} potential issue(s) ({file_size:,} bytes)")
        for issue in issues:
            print(f"   - {issue}")
        all_papers_clean = False

print("\n" + "="*70)
if all_papers_clean:
    print("SUCCESS: All papers have been successfully anonymized!")
    print("\nOutput files saved to /root/redacted/:")
    for i in range(1, 4):
        print(f"  paper{i}.pdf")
else:
    print("Review the issues above and determine if they need attention.")
print("="*70)
